pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(hello) = bytes.strip_prefix("{\"v\":2,\"hello\":\"") {
        if let Some(hello) = hello.strip_suffix("\"}") {
            return Ok(Msg::Hello(hello.to_owned()));
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("{{\"v\":2,\"hello\":\"{}\"}}", value),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let encoded = encode(&Msg::Hello("world".into()));
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(value)) if value == "world"));
    }
}

